[FunctionName("ProcessOrder")]
public static async Task Run(
    [ServiceBusTrigger("orders-queue", Connection = "ServiceBusConnection")] Order order,
    ILogger log)
{
    log.LogInformation($"Processing order: {order.Id}");

    // Validate inventory
    var inventory = await _inventoryService.CheckAsync(order);
    if (!inventory.IsAvailable)
    {
        await _serviceBus.SendAsync("failed-orders", order);
        return;
    }

    // Process payment
    await _paymentService.ChargeAsync(order);

    // Send confirmation
    await _emailService.SendAsync(order.CustomerEmail, "Order Confirmed");
}
